#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t n = 4;
    int *z = calloc(n, sizeof(int));      /* 保证全 0 */
    int sum = 0;
    for (size_t i = 0; i < n; i++) sum += z[i];
    printf("calloc 求和 = %d (必为 0)\n", sum);

    int *d = malloc(n * sizeof(int));     /* 内容不确定，不可依赖 */
    printf("malloc 内容不确定，任何具体值都不可假设\n");

    free(z); free(d);
    z = d = NULL;
    return 0;
}
